import React, { useState, useEffect } from "react";
import { ethers } from "ethers";
import LandRegistryData from "./contracts/LandRegistry.json";
import LoanBankData from "./contracts/LoanBank.json";

// Extract ABIs from the JSON artifacts
const landRegistryABI = LandRegistryData.abi;
const loanBankABI = LoanBankData.abi;

// Smart contract addresses (update if needed)
const landRegistryAddress = "0xeB4770294ccC6dBdaAFe6905c08C91D56B6d53B1";
const loanBankAddress = "0x2D7886b78275600A69cE61Bf9DADC46D15bc3367";

function App() {
  const [account, setAccount] = useState(null);
  const [provider, setProvider] = useState(null);
  const [signer, setSigner] = useState(null);
  const [landRegistry, setLandRegistry] = useState(null);
  const [loanBank, setLoanBank] = useState(null);
  const [message, setMessage] = useState("");

  // Form state for Land Registration
  const [regPlotId, setRegPlotId] = useState("");
  const [regMetadata, setRegMetadata] = useState("");
  const [regOwner, setRegOwner] = useState("");

  // Form state for Loan Application
  const [loanPrincipal, setLoanPrincipal] = useState("");
  const [loanInterest, setLoanInterest] = useState("");

  // Form state for Land Purchase
  const [purchasePlotId, setPurchasePlotId] = useState("");

  // Form state for Loan Repayment
  const [repayAmount, setRepayAmount] = useState("");

  useEffect(() => {
    async function loadBlockchainData() {
      if (window.ethereum) {
        try {
          // Connect to Ethereum provider (e.g., MetaMask)
          const provider = new ethers.providers.Web3Provider(window.ethereum);
          await window.ethereum.request({ method: "eth_requestAccounts" });
          const signer = provider.getSigner();
          const account = await signer.getAddress();

          setAccount(account);
          setProvider(provider);
          setSigner(signer);

          // Debug logs for ABIs
          console.log("Land Registry ABI:", landRegistryABI);
          console.log("Loan Bank ABI:", loanBankABI);

          // Initialize smart contract instances using the signer
          const landRegistryContract = new ethers.Contract(
            landRegistryAddress,
            landRegistryABI,
            signer
          );
          const loanBankContract = new ethers.Contract(
            loanBankAddress,
            loanBankABI,
            signer
          );

          setLandRegistry(landRegistryContract);
          setLoanBank(loanBankContract);
        } catch (error) {
          console.error("Error loading blockchain data:", error);
          alert("Error connecting to blockchain. Please try again.");
        }
      } else {
        alert("Please install MetaMask!");
      }
    }
    loadBlockchainData();
  }, []);

  // Handler: Land Registration (FR1)
  async function handleRegisterLand(e) {
    e.preventDefault();
    try {
      // Call the registerLand function on the LandRegistry contract.
      // Assuming the smart contract function signature is:
      // function registerLand(uint plotId, string memory metadata, address owner) public
      const tx = await landRegistry.registerLand(regPlotId, regMetadata, regOwner);
      await tx.wait();
      alert("Land registered successfully and NFT issued!");
      setMessage("Land registered successfully!");
    } catch (error) {
      console.error(error);
      alert("Land registration failed.");
      setMessage("Land registration failed.");
    }
  }

  // Handler: Loan Application (FR2)
  async function handleApplyForLoan(e) {
    e.preventDefault();
    try {
      // Call the createLoan function on the LoanBank contract.
      // Assuming the function signature is:
      // function createLoan(uint principal, uint interestRate) public
      const tx = await loanBank.createLoan(loanPrincipal, loanInterest);
      await tx.wait();
      alert("Loan applied successfully!");
      setMessage("Loan applied successfully!");
    } catch (error) {
      console.error(error);
      alert("Loan application failed.");
      setMessage("Loan application failed.");
    }
  }

  // Handler: Land Purchase (FR3)
  async function handlePurchaseLand(e) {
    e.preventDefault();
    try {
      // Call the purchaseLand function on the LandRegistry contract.
      // Assuming the function signature is:
      // function purchaseLand(uint plotId) public
      const tx = await landRegistry.purchaseLand(purchasePlotId);
      await tx.wait();
      alert("Land purchased successfully!");
      setMessage("Land purchased successfully!");
    } catch (error) {
      console.error(error);
      alert("Land purchase failed.");
      setMessage("Land purchase failed.");
    }
  }

  // Handler: Loan Repayment (FR4)
  async function handleRepayLoan(e) {
    e.preventDefault();
    try {
      // Call the repayLoan function on the LoanBank contract.
      // Assuming the function signature is:
      // function repayLoan(uint amount) public
      const tx = await loanBank.repayLoan(repayAmount);
      await tx.wait();
      alert("Loan repaid successfully!");
      setMessage("Loan repaid successfully!");
    } catch (error) {
      console.error(error);
      alert("Loan repayment failed.");
      setMessage("Loan repayment failed.");
    }
  }

  // Handler: Default Checking (FR5)
  async function handleCheckDefault(e) {
    e.preventDefault();
    try {
      // Call the checkDefault function on the LoanBank contract.
      // Assuming the function signature is:
      // function checkDefault(address developer) public
      const tx = await loanBank.checkDefault(account);
      await tx.wait();
      alert("Default check completed!");
      setMessage("Default check completed!");
    } catch (error) {
      console.error(error);
      alert("Default check failed.");
      setMessage("Default check failed.");
    }
  }

  return (
    <div style={{ padding: "20px" }}>
      <h1>Land & Loan Management</h1>
      <p>
        <strong>Connected Account:</strong> {account}
      </p>
      {message && <p>{message}</p>}

      <hr />
      <h2>Land Registration</h2>
      <form onSubmit={handleRegisterLand}>
        <div>
          <label>Plot ID: </label>
          <input
            type="text"
            value={regPlotId}
            onChange={(e) => setRegPlotId(e.target.value)}
            placeholder="Enter Plot ID"
            required
          />
        </div>
        <div>
          <label>Metadata: </label>
          <input
            type="text"
            value={regMetadata}
            onChange={(e) => setRegMetadata(e.target.value)}
            placeholder="Enter Metadata"
            required
          />
        </div>
        <div>
          <label>Owner Address: </label>
          <input
            type="text"
            value={regOwner}
            onChange={(e) => setRegOwner(e.target.value)}
            placeholder="Enter Owner Address"
            required
          />
        </div>
        <button type="submit">Register Land</button>
      </form>

      <hr />
      <h2>Loan Application</h2>
      <form onSubmit={handleApplyForLoan}>
        <div>
          <label>Principal (ETH): </label>
          <input
            type="number"
            value={loanPrincipal}
            onChange={(e) => setLoanPrincipal(e.target.value)}
            placeholder="Enter Principal"
            required
          />
        </div>
        <div>
          <label>Interest Rate (%): </label>
          <input
            type="number"
            step="0.1"
            value={loanInterest}
            onChange={(e) => setLoanInterest(e.target.value)}
            placeholder="Enter Interest Rate"
            required
          />
        </div>
        <button type="submit">Apply for Loan</button>
      </form>

      <hr />
      <h2>Land Purchase</h2>
      <form onSubmit={handlePurchaseLand}>
        <div>
          <label>Plot ID: </label>
          <input
            type="text"
            value={purchasePlotId}
            onChange={(e) => setPurchasePlotId(e.target.value)}
            placeholder="Enter Plot ID to Purchase"
            required
          />
        </div>
        <button type="submit">Purchase Land</button>
      </form>

      <hr />
      <h2>Loan Repayment</h2>
      <form onSubmit={handleRepayLoan}>
        <div>
          <label>Repayment Amount (ETH): </label>
          <input
            type="number"
            value={repayAmount}
            onChange={(e) => setRepayAmount(e.target.value)}
            placeholder="Enter Repayment Amount"
            required
          />
        </div>
        <button type="submit">Repay Loan</button>
      </form>

      <hr />
      <h2>Default Check</h2>
      <button onClick={handleCheckDefault}>Check Default</button>
    </div>
  );
}

export default App;
